        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    # a third of the shards go to Treasure (more gold), the rest split strength/health
    let treasure_n = floor( shards_bought / 3 )
    let rem_shards = shards_bought - treasure_n
    let strength_n = floor( rem_shards / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard(stat_strength()), strength_n )
    buy( shard(stat_health()), rem_shards - strength_n )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# hurt and under threat away from spawn: fall back toward spawn rather than trade in place
if not at_spawn and health() < 0.4 * max_health() and in_danger():
    move_towards( closest( spawn_region(ally()) ) )
    end_turn()

# hurt and outnumbered by visible enemies (more enemies than allies within 5): disengage
# toward spawn instead of trading into a losing fight
if not at_spawn and health() < 0.6 * max_health() and enemies_within(5) > allies_within(5):
    move_towards( closest( spawn_region(ally()) ) )
    end_turn()

# retreat at 20% health normally, but at 50% when carrying gems
if not at_spawn and (health() < 0.2 * max_health() or (gems() > 0 and health() < 0.5 * max_health())):
    recall()
    end_turn()

let targets = filter( enemies_visible(), in_attack_range() )
if exists(first(targets)):
    # focus fire: hit the weakest enemy in reach
    let enemy = weakest(targets)
    # ranged champions step off an adjacent melee enemy, then shoot from range
    if i_am_ranged() and distance(unit_position(enemy), position()) <= 1:
        move_away_from( unit_position(enemy) )
    # hurt in a fight: shield up first if a shield ability is ready
    if health() < 0.5 * max_health():
        if ability_ready(0) and slot_is_shield(0):
            cast_self(0)
        elif ability_ready(1) and slot_is_shield(1):
            cast_self(1)
    # stuns and damage abilities go on the focus target
    if ability_ready(0) and (slot_is_stun(0) or slot_is_damage(0) or slot_is_aoe(0)):
        cast_at_unit(0, enemy)
    if ability_ready(1) and (slot_is_stun(1) or slot_is_damage(1) or slot_is_aoe(1)):
        cast_at_unit(1, enemy)
    if can_attack():
        attack(enemy)
    end_turn()

if gems() > 0:
    # prefer open altars outside monolith reach
    let safe_altars = minus( minus(altars(), locked_altars()), ring(monolith_tiles(), 5) )
    let altar = first( filter( safe_altars, within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    if exists(first(safe_altars)):
        move_towards( closest( ring(safe_altars, 1) ) )
        end_turn()
    # fallback: any open altar, so carriers never idle
    let any_altars = minus( altars(), locked_altars() )
    let altar2 = first( filter( any_altars, within(1, position()) ) )
    if exists(altar2):
        tribute(altar2)
        end_turn()
    move_towards( closest( ring(any_altars, 1) ) )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(0):
        cast_at_unit(0, camp)
    if ability_ready(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

let goals = minus( camp_spawns, respawning_visible_spawns() )
# gem camps first: gems decide games
let gem_goals = minus( gem_cluster_tiles(), respawning_visible_spawns() )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(goals, position()):
    end_turn()

if exists( closest(gem_goals) ):
    move_towards( closest(gem_goals) )
else:
    move_towards( closest(goals) )

let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()
